    buffer.skip(8);

    // Skip optional extra fields.
    // +---+---+=================================+
    // | XLEN  |...XLEN bytes of "extra field"...| (more-->)
    // +---+---+=================================+
    if (((flags >> FEXTRA) & 1) == 1) {
      require(2, deadline);
      if (fhcrc) updateCrc(buffer, 0, 2);
      int xlen = buffer.readShortLe() & 0xffff;
      require(xlen, deadline);
      if (fhcrc) updateCrc(buffer, 0, xlen);
      buffer.skip(xlen);
    }

