    // Skip an optional 0-terminated comment.
    // +===================================+
    // |...file comment, zero-terminated...| (more-->)
    // +===================================+
    if (((flags >> FCOMMENT) & 1) == 1) {
      long index = OkBuffers.seek(buffer, (byte) 0, source, deadline);
      if (fhcrc) updateCrc(buffer, 0, index + 1);
      buffer.skip(index + 1);
