    @Override
    public TitanType getType(String name) {
        verifyOpen();

        Long typeId = typeCache.get(name);
        if (typeId != null) {
            InternalVertex typeVertex = vertexCache.get(typeId, existingVertexRetriever);
            if (typeVertex != null)
