        if (et == null) {
            return config.getAutoEdgeTypeMaker().makeKey(makeKey(name));
        } else if (et.isPropertyKey()) {
            return (TitanKey) et;
        } else
            throw new IllegalArgumentException("The type of given name is not a key: " + name);

